import{_ as t,o,c as i,a2 as s}from"./chunks/framework.mrTIYZc5.js";const p=JSON.parse('{"title":"Troubleshooting & Diagnostics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),a={name:"guide/troubleshooting.md"};function n(r,e,l,c,d,h){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="troubleshooting-diagnostics" tabindex="-1">Troubleshooting &amp; Diagnostics <a class="header-anchor" href="#troubleshooting-diagnostics" aria-label="Permalink to &quot;Troubleshooting &amp; Diagnostics&quot;">​</a></h1><p>DSO is designed to fail securely. When a synchronization or rotation event fails, the system prioritizes existing secret integrity over applying potentially corrupted or unauthorized updates.</p><hr><h2 id="_1-provider-authentication-failures" tabindex="-1">1. Provider Authentication Failures <a class="header-anchor" href="#_1-provider-authentication-failures" aria-label="Permalink to &quot;1. Provider Authentication Failures&quot;">​</a></h2><p><strong>Symptom</strong>: <code>ERROR: [Watcher] Failed to fetch secret &#39;myapp/db&#39;: AccessDenied</code></p><p>DSO relies on <strong>Machine Identity</strong>. Authentication failures typically indicate a mismatch between the host&#39;s IAM profile and the required vault permissions.</p><p><strong>Diagnostic Steps</strong>:</p><ol><li><strong>Verify IAM Policy</strong>: Ensure the host&#39;s IAM Role (AWS) or Managed Identity (Azure) has explicit <code>GetSecretValue</code> permissions for the specific Resource ARN.</li><li><strong>Context Check</strong>: If running in a containerized environment (e.g., Docker-in-Docker), ensure the cloud metadata service (IMDS) is reachable from within the network namespace.</li><li><strong>Manual Resolution Test</strong>: Use the DSO CLI to verify connectivity independently of the rotation engine:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">secret-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div></li></ol><hr><h2 id="_2-secret-drift-rotation-stalls" tabindex="-1">2. Secret Drift &amp; Rotation Stalls <a class="header-anchor" href="#_2-secret-drift-rotation-stalls" aria-label="Permalink to &quot;2. Secret Drift &amp; Rotation Stalls&quot;">​</a></h2><p><strong>Symptom</strong>: Secret updated in Vault, but container remains on the legacy version.</p><p><strong>Diagnostic Steps</strong>:</p><ol><li><strong>Watcher Mode</strong>: Verify <code>agent.watch.polling_interval</code> in <code>dso.yaml</code>. If the interval is high (e.g., <code>10m</code>), the &quot;Reconciliation Gap&quot; may be expected.</li><li><strong>Debouncer Interaction</strong>: DSO ignores rapid successions of vault updates to prevent &quot;flapping.&quot; Check logs for <code>[Debouncer] Update suppressed</code>.</li><li><strong>Label Verification</strong>: Ensure the target container has <code>dso.reloader=true</code>. DSO ignores all containers without this explicit opt-in label.</li></ol><hr><h2 id="_3-atomic-rotation-failures-rolling-strategy" tabindex="-1">3. Atomic Rotation Failures (Rolling Strategy) <a class="header-anchor" href="#_3-atomic-rotation-failures-rolling-strategy" aria-label="Permalink to &quot;3. Atomic Rotation Failures (Rolling Strategy)&quot;">​</a></h2><p><strong>Symptom</strong>: <code>ERROR: [Reloader] Rolling update failed for &#39;api&#39;: Healthcheck timeout</code></p><p>When using the <code>rolling</code> strategy, DSO starts a new container and waits for it to become <code>healthy</code> before removing the old one. If the new container fails its healthcheck, DSO aborts the rotation.</p><p><strong>Diagnostic Steps</strong>:</p><ol><li><strong>Healthcheck Definition</strong>: Ensure a valid <code>healthcheck</code> is defined in <code>docker-compose.yml</code>.</li><li><strong>Logs Inspection</strong>: Check the logs of the &quot;Candidate&quot; container (usually named <code>&lt;service&gt;_dso_new</code>) to see if the application failed to boot with the new secret.</li><li><strong>Timeout Adjustment</strong>: If the application has a long cold-start time, increase <code>agent.rotation.health_check_timeout</code>.</li></ol><hr><h2 id="_4-signal-based-reload-issues-sighup" tabindex="-1">4. Signal-Based Reload Issues (SIGHUP) <a class="header-anchor" href="#_4-signal-based-reload-issues-sighup" aria-label="Permalink to &quot;4. Signal-Based Reload Issues (SIGHUP)&quot;">​</a></h2><p><strong>Symptom</strong>: <code>INFO: [Reloader] Signal SIGHUP sent to &#39;proxy&#39;</code>, but configuration remains old.</p><p><strong>Diagnostic Steps</strong>:</p><ol><li><strong>PID 1 Requirement</strong>: DSO sends signals to the container&#39;s PID 1. If your entrypoint is a shell script (<code>sh -c ...</code>), the signal may not be propagated to the application. Use <code>exec</code> in your entrypoint scripts.</li><li><strong>App Support</strong>: Verify that the application (e.g., Nginx, Go-binary) actually implements a handler for <code>SIGHUP</code> to reload its configuration from the environment or filesystem.</li></ol><hr><h2 id="_5-socket-connectivity" tabindex="-1">5. Socket Connectivity <a class="header-anchor" href="#_5-socket-connectivity" aria-label="Permalink to &quot;5. Socket Connectivity&quot;">​</a></h2><p><strong>Symptom</strong>: <code>failed to connect to /run/docker/plugins/dso.sock: connection refused</code></p><p><strong>Diagnostic Steps</strong>:</p><ol><li><strong>Plugin Status</strong>: Verify the DSO plugin is enabled: <code>docker plugin ls</code>.</li><li><strong>Daemon Logs</strong>: Inspect the plugin&#39;s internal logs via the host&#39;s journal:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># For native installs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div></li></ol><h2 id="diagnostic-reference" tabindex="-1">Diagnostic Reference <a class="header-anchor" href="#diagnostic-reference" aria-label="Permalink to &quot;Diagnostic Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>docker dso version</code></td><td>Check binary version and build hash</td></tr><tr><td><code>docker dso fetch &lt;name&gt;</code></td><td>Test vault connectivity and resolution</td></tr><tr><td><code>docker dso watch</code></td><td>Foreground watcher logs (real-time diagnostics)</td></tr><tr><td><code>docker dso inspect &lt;id&gt;</code></td><td>View active secret mappings for a container</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/architecture.html">System Architecture</a></strong>: Understand the internal reconciliation loop.</li><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: Detailed boundaries and threat mitigations.</li><li><strong><a href="/docs/guide/production-readiness.html">Production Readiness</a></strong>: Best practices to avoid common issues.</li></ul>`,33)])])}const u=t(a,[["render",n]]);export{p as __pageData,u as default};
